  List<CraftedGear> InventoryItems(){
   city.EnsureGearRolls();var result=city.craftedGear.FindAll(g=>city.EquippedRoll(g.slot)?.id!=g.id&&(inventoryFilter==0||inventoryFilter==1&&g.slot<8||inventoryFilter==2&&g.slot==9||inventoryFilter==3&&g.slot==8||inventoryFilter==4&&InventoryFavourite(g.id))&&(GearRollRules.BaseName(g)+" "+PaperSlotName(g.slot)).IndexOf(inventorySearch,StringComparison.OrdinalIgnoreCase)>=0);
   result.Sort((a,b)=>inventorySort==1?b.id.CompareTo(a.id):inventorySort==2&&EquipmentTier(a)!=EquipmentTier(b)?EquipmentTier(b).CompareTo(EquipmentTier(a)):a.slot!=b.slot?a.slot.CompareTo(b.slot):b.id.CompareTo(a.id));return result;
  }
  void SelectInventoryItem(int id){var item=city.FindRoll(id);if(item==null)return;gearBagSelected=id;gearBagSlot=item.slot;gearSlot=item.slot;inventorySearchEditing=false;}
  void EquipInventoryItem(){var item=city.FindRoll(gearBagSelected);if(item==null||city.EquippedRoll(item.slot)?.id==item.id)return;if(city.EquipRoll(item.id)){RefreshMetalGear();Save();notice=GearRollRules.BaseName(item)+" equipped.";inventoryCompare=false;inventoryFocus=-1;}}
  void ToggleInventoryCompare(){var item=city.FindRoll(gearBagSelected);if(item!=null){inventoryCompare=!inventoryCompare;inventoryFocus=inventoryCompare&&city.EquippedRoll(item.slot)?.id!=item.id?1:-1;}}
  void ToggleInventoryFavourite(){if(city.FindRoll(gearBagSelected)==null)return;if(city.favouriteGearIds==null)city.favouriteGearIds=new List<int>();if(!city.favouriteGearIds.Remove(gearBagSelected))city.favouriteGearIds.Add(gearBagSelected);Save();}
  void InventoryAction(Rect rect,string label,Action action,bool enabled=true,int item=0){
