   int index=inventoryControls.Count;if(enabled)inventoryControls.Add(new InventoryControl{rect=rect,action=action,item=item});
   ArchiveButton(rect,label,action,enabled);if(enabled&&(!inventoryCompare||inventoryDrawingOverlay)&&inventoryFocus==index)DrawMenuNavigationFocus(rect,label);
  }
