   var entries=InventoryItems();int pages=Math.Max(1,(entries.Count+23)/24);gearBagPage=Mathf.Clamp(gearBagPage,0,pages-1);if(city.FindRoll(gearBagSelected)==null&&entries.Count>0)SelectInventoryItem(entries[0].id);
