   InventoryAction(new Rect(560,675,120,29),"Previous",()=>gearBagPage--,gearBagPage>0);GUI.Label(new Rect(690,678,180,25),"Page "+(gearBagPage+1)+" / "+pages,ArchiveType(13,archiveMuted));InventoryAction(new Rect(1390,675,145,29),"Next",()=>gearBagPage++,gearBagPage<pages-1);
   var selected=city.FindRoll(gearBagSelected);if(selected!=null){DrawGearArtwork(new Rect(560,719,64,64),selected);GUI.Label(new Rect(637,719,530,27),GearRollRules.BaseName(selected),ArchiveType(20,archiveIvory,true));var metrics=GearItemMetrics.From(selected);GUI.Label(new Rect(637,754,510,24),PaperSlotName(selected.slot)+" / "+EquipmentTypeLabel(selected)+" / "+(selected.slot==9?metrics.damage.ToString("0.##")+" damage":metrics.armour.ToString("0.##")+" armour")+" / "+metrics.mass.ToString("0.##")+" kg",ArchiveType(14,archiveMuted));InventoryAction(new Rect(1190,720,155,32),InventoryFavourite(selected.id)?"Unfavourite":"Favourite",ToggleInventoryFavourite);InventoryAction(new Rect(1355,720,180,32),(menuControllerActive?"Y  /  ":"")+"Compare",ToggleInventoryCompare);InventoryAction(new Rect(1190,763,345,35),(menuControllerActive?"A  /  ":"")+(city.EquippedRoll(selected.slot)?.id==selected.id?"Equipped":"Equip"),EquipInventoryItem,city.EquippedRoll(selected.slot)?.id!=selected.id);}
   GUI.Label(new Rect(52,882,1495,18),notice!=""?notice:menuControllerActive?"D-pad / stick: navigate · A: equip selected item · Y: compare · B: back · LB / RB: pages":"Click an item to select · Enter: equip item · C: compare · Escape: back",ArchiveType(14,archiveMuted));
