   var equipped=city.EquippedRoll(item.slot);DrawGearArtwork(new Rect(330,225,84,84),equipped);DrawGearArtwork(new Rect(815,225,84,84),item);GUI.Label(new Rect(430,228,355,26),"CURRENTLY EQUIPPED",ArchiveType(13,archiveGold,true));GUI.Label(new Rect(430,264,355,58),equipped==null?"Empty slot":GearRollRules.BaseName(equipped),ArchiveType(20,archiveIvory,true));GUI.Label(new Rect(915,228,355,26),"SELECTED ITEM",ArchiveType(13,archiveGold,true));GUI.Label(new Rect(915,264,355,58),GearRollRules.BaseName(item),ArchiveType(20,archiveIvory,true));
   var data=new GearComparisonData(item,equipped,city.Loadout);float y=333;foreach(var change in data.primary){DrawInventoryDelta(change,y);y+=35;}foreach(var change in data.bonuses){DrawInventoryDelta(change,y);y+=30;}if(!data.HasChanges)GUI.Label(new Rect(335,y,920,26),"Same stats as equipped gear.",ArchiveType(16,archiveMuted));
   InventoryAction(new Rect(330,758,285,39),menuControllerActive?"B / Back":"Back to inventory",()=>{inventoryCompare=false;inventoryFocus=-1;});InventoryAction(new Rect(630,758,300,39),(menuControllerActive?"A / ":"")+"Equip selected",EquipInventoryItem,!data.AlreadyEquipped);InventoryAction(new Rect(945,758,325,39),"Enchant at Mystic",()=>OpenMystic(item.id,true),city.mysticLevel>0);
