  void DrawInventoryDelta(GearStatChange change,float y){GUI.Label(new Rect(335,y,350,28),change.label,ArchiveType(15,archiveIvory));GUI.Label(new Rect(690,y,330,28),change.Transition,ArchiveType(15,archiveMuted));GUI.Label(new Rect(1030,y,230,28),change.DeltaText,ArchiveType(17,!change.Changed?archiveMuted:change.Better?new Color(.57f,.85f,.53f):new Color(.96f,.48f,.40f),true,TextAnchor.UpperRight));}
  bool ReadInventoryInput(){
   if(!InventoryScreenOpen)return false;var key=Keyboard.current;var pad=PreferredPad;if(pad?.rightStickButton.wasPressedThisFrame==true){FocusResourceBar();return true;}if(resourceFocus||resourceCategory>=0||key?.f2Key.wasPressedThisFrame==true){ReadResourceController();if(key?.escapeKey.wasPressedThisFrame==true||pad?.buttonEast.wasPressedThisFrame==true)LeaveResourceBar();return true;}
   if(inventorySearchEditing){if(key?.escapeKey.wasPressedThisFrame==true||key?.enterKey.wasPressedThisFrame==true||pad?.buttonEast.wasPressedThisFrame==true||pad?.buttonSouth.wasPressedThisFrame==true){inventorySearchEditing=false;inventoryClearSearchFocus=true;}return true;}
   if(key?.escapeKey.wasPressedThisFrame==true||pad?.buttonEast.wasPressedThisFrame==true){if(inventoryCompare){inventoryCompare=false;inventoryFocus=-1;}else if(gearBagOpen)CloseGearBag();else{tab=0;selection=0;}return true;}
   if(pad?.buttonNorth.wasPressedThisFrame==true||key?.cKey.wasPressedThisFrame==true){ToggleInventoryCompare();return true;}
   if(pad?.leftShoulder.wasPressedThisFrame==true)gearBagPage=Math.Max(0,gearBagPage-1);if(pad?.rightShoulder.wasPressedThisFrame==true)gearBagPage++;
   if(key?.fKey.wasPressedThisFrame==true)ToggleInventoryFavourite();
   int dx=key?.rightArrowKey.wasPressedThisFrame==true||pad?.dpad.right.wasPressedThisFrame==true?1:key?.leftArrowKey.wasPressedThisFrame==true||pad?.dpad.left.wasPressedThisFrame==true?-1:0;
   int dy=key?.downArrowKey.wasPressedThisFrame==true||pad?.dpad.down.wasPressedThisFrame==true?1:key?.upArrowKey.wasPressedThisFrame==true||pad?.dpad.up.wasPressedThisFrame==true?-1:0;
   navigationCooldown-=Time.unscaledDeltaTime;if(pad!=null&&navigationCooldown<=0){var axis=pad.leftStick.ReadValue();if(Mathf.Abs(axis.x)>.6f)dx=axis.x>0?1:-1;else if(Mathf.Abs(axis.y)>.6f)dy=axis.y>0?-1:1;if(dx!=0||dy!=0)navigationCooldown=.19f;}
   if(inventoryControls.Count>0){if(inventoryFocus<0)return true;inventoryFocus=Mathf.Clamp(inventoryFocus,0,inventoryControls.Count-1);if(dx!=0||dy!=0){var origin=inventoryControls[inventoryFocus].rect.center;float best=float.MaxValue;int next=inventoryFocus;for(int i=0;i<inventoryControls.Count;i++){var delta=inventoryControls[i].rect.center-origin;float along=delta.x*dx+delta.y*dy,across=Mathf.Abs(delta.x*dy-delta.y*dx);if(along<=1)continue;float score=along+across*3;if(score<best){best=score;next=i;}}inventoryFocus=next;var focus=inventoryControls[next];if(focus.item!=0)SelectInventoryItem(focus.item);}
    if(pad?.buttonSouth.wasPressedThisFrame==true||key?.enterKey.wasPressedThisFrame==true){var focus=inventoryControls[inventoryFocus];if(focus.item!=0){SelectInventoryItem(focus.item);EquipInventoryItem();}else focus.action();}}
   return true;
  }
